import{_ as a,a as t,c as s,ac as i}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 98 Whose is it? Whose are they?","description":"学习 名词性物主代词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 98 Whose is it? Whose are they?","description":"学习 名词性物主代词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 名词性物主代词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 97 A small blue case","link":"/life/english/new-concept/book-1/unit-05/lesson-097"},"next":{"text":"第一册：英语初阶 · Lesson 99 Ow!","link":"/life/english/new-concept/book-1/unit-05/lesson-099"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 97 A small blue case","link":"/life/english/new-concept/book-1/unit-05/lesson-097"},"next":{"text":"第一册：英语初阶 · Lesson 99 Ow!","link":"/life/english/new-concept/book-1/unit-05/lesson-099"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-05/lesson-098.md","filePath":"life/english/new-concept/book-1/unit-05/lesson-098.md"}'),o={name:"life/english/new-concept/book-1/unit-05/lesson-098.md"};function n(r,e,l,h,c,d){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="第一册-英语初阶-·-lesson-98-whose-is-it-whose-are-they" tabindex="-1">第一册：英语初阶 · Lesson 98 Whose is it? Whose are they? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-98-whose-is-it-whose-are-they" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 98 Whose is it? Whose are they?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元 5</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-097">配套课 Lesson 97</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>辨认行李并确认归属 本课要掌握名词性物主代词，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>case</td><td>/keɪs/</td><td>n.</td><td>箱子</td><td>a blue case</td></tr><tr><td>label</td><td>/ˈleɪbl/</td><td>n.</td><td>标签</td><td>a luggage label</td></tr><tr><td>mine</td><td>/maɪn/</td><td>pron.</td><td>我的（东西）</td><td>it is mine</td></tr><tr><td>yours</td><td>/jɔːz/</td><td>pron.</td><td>你的（东西）</td><td>is this yours</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>a small blue case — 尺寸在颜色前</li><li>this one is mine — mine 独立作表语</li></ul><h2 id="语法讲解-名词性物主代词" tabindex="-1">语法讲解：名词性物主代词 <a class="header-anchor" href="#语法讲解-名词性物主代词" aria-label="Permalink to &quot;语法讲解：名词性物主代词&quot;">​</a></h2><p>my/your/her/our/their 后面接名词；mine/yours/hers/ours/theirs 本身能代表“某人的东西”，后面不再接名词。his 两种用法同形。Whose is this case? 可答 It is mine。物主代词随拥有者变化，不随被拥有的东西变复数；两只箱子属于我仍用 mine。多个形容词修饰名词时，尺寸常在颜色前。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Are these keys yours or hers?</p></blockquote><p>这些钥匙是你的还是她的？</p><p>These keys 为复数主语，are 前置；yours 与 hers 都独立代表“某人的钥匙”，两者之间用 or 提供选择。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不能写 mine suitcase；名词前用 my，独立使用才用 mine。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“Are these keys yours or hers?”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Are these keys yours or hers? The small green suitcase is mine.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“辨认行李并确认归属”写两至三句，再读给同伴听。至少使用一次名词性物主代词，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>These keys 为复数主语，are 前置；yours 与 hers 都独立代表“某人的钥匙”，两者之间用 or 提供选择。 The small green suitcase 是主语，small 表尺寸、green 表颜色；mine 独立作表语，后不再接 suitcase。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>选择 her/hers：Are these keys ___?</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> hers</p><p><strong>解析：</strong> 按本课规则判断：my/your/her/our/their 后面接名词；mine/yours/hers/ours/theirs 本身能代表“某人的东西”，后面不再接名词。his 两种用法同形。Whose is this case? 可答 It is mine。物主代词随拥有者变化，不随被拥有的东西变复数；两只箱子属于我仍用 mine。多个形容词修饰名词时，尺寸常在颜色前。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“这些钥匙是你的还是她的？”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Are these keys yours or hers?</p><p><strong>解析：</strong> These keys 为复数主语，are 前置；yours 与 hers 都独立代表“某人的钥匙”，两者之间用 or 提供选择。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：The small green suitcase is mine.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 那个绿色的小手提箱是我的。</p><p><strong>解析：</strong> The small green suitcase 是主语，small 表尺寸、green 表颜色；mine 独立作表语，后不再接 suitcase。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：名词性物主代词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-05/lesson-097">上一课</a> · <a href="/life/english/new-concept/book-1/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-05/lesson-099">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=a(o,[["render",n]]);export{p as __pageData,m as default};
